import{_ as o,o as r,c as i,a2 as t}from"./chunks/framework.DnrXFDHb.js";const h=JSON.parse('{"title":"ADR-0002: Use SPI for Open Core Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0002-use-spi-for-open-core.md","filePath":"adr/0002-use-spi-for-open-core.md"}'),a={name:"adr/0002-use-spi-for-open-core.md"};function n(s,e,c,l,p,d){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0002-use-spi-for-open-core-architecture" tabindex="-1">ADR-0002: Use SPI for Open Core Architecture <a class="header-anchor" href="#adr-0002-use-spi-for-open-core-architecture" aria-label="Permalink to &quot;ADR-0002: Use SPI for Open Core Architecture&quot;">​</a></h1><p><strong>Date:</strong> 2026-06-12 <strong>Status:</strong> Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Mozhno использует модель Open Core: community edition с полной функциональностью + возможность подключения enterprise-расширений (SSO, аудит, биллинг, квоты, вебхуки).</p><p>Нужен механизм, позволяющий заменять реализации без форка кодовой базы, с приоритетами и поддержкой нескольких провайдеров одновременно.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Использован <strong>Service Provider Interface (SPI)</strong> — набор Java-интерфейсов в модуле <code>mozhno-spi</code>, которые реализуются в <code>mozhno-core</code> (дефолтные реализации) или во внешних JAR-файлах (enterprise-расширения).</p><p>Spring автоматически собирает все бины, реализующие SPI-интерфейсы, через <code>List&lt;SPI&gt;</code>. Провайдеры сортируются по <code>priority()</code> и пробуются по цепочке.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Позитивные:</strong></p><ul><li>Zero-cost для community edition: дефолтные реализации всегда доступны.</li><li>Enterprise-расширения — это обычные Spring-бины в отдельном JAR. Никакой магии с classpath, plugin-системами или OSGi.</li><li>Приоритеты гарантируют детерминированный порядок: custom-провайдер может перехватить запрос до дефолтного.</li><li>Тестируемость: каждый SPI можно замокать независимо.</li></ul><p><strong>Негативные:</strong></p><ul><li>Нельзя гарантировать порядок загрузки нескольких enterprise-JAR (решается приоритетами).</li><li>Сложность отладки: цепочка провайдеров может быть длинной.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><ul><li><code>AuthenticationProviderSpi</code> — цепочка: JWT → API Key → (SSO/LDAP в enterprise)</li><li><code>AuthenticationFlowSpi</code> — логин: password → (Google/SAML в enterprise)</li><li><code>QuotaSpi</code> — NoOpQuotaProvider → (Plan-based quota в enterprise)</li><li><code>BillingSpi</code> — OpenSourceBillingProvider → (Stripe-based в enterprise)</li><li><code>FeatureGateSpi</code> — все фичи включены → (Tier-based gating в enterprise)</li></ul>',15)])])}const S=o(a,[["render",n]]);export{h as __pageData,S as default};
